structure.mermaidSource:
flowchart TD
  start(["Início: Forma verbal candidata à ditongação (-ei-)"]) --> dec_grupo{"O verbo termina em -EAR ou integra o acrônimo MARIO?"}
  dec_grupo -- "Não (-IAR regular)" --> res_proibido_iar["Ditongação PROIBIDA<br/>Ex.: maquio, premia, copiem"]
  dec_grupo -- "Sim (-EAR ou MARIO)" --> dec_tempo{"O tempo/modo exigido é Presente do Indicativo ou Subjuntivo?"}
  dec_tempo -- "Não (Pretérito / Futuro / Infinitivo)" --> res_proibido_tempo["Ditongação PROIBIDA<br/>Ex.: ceei, cearei, frearmos"]
  dec_tempo -- "Sim (Presente Ind. ou Subj.)" --> dec_pessoa{"A flexão é de 1ª ou 2ª pessoa do plural (Nós / Vós)?"}
  dec_pessoa -- "Sim (Nós / Vós - Arrizotônicas)" --> res_proibido_nos_vos["Ditongação PROIBIDA<br/>Ex.: nós passeamos, nós mediamos"]
  dec_pessoa -- "Não (Eu / Tu / Ele / Eles - Rizotônicas)" --> res_ditongacao_obrigatoria["Ditongação OBRIGATÓRIA (-ei-)<br/>Ex.: eu passeio, ele anseia, eles incendeiam"]
